float plStagger(float q) { return mod(q, 2.0) * 0.5 + (kh1(q * 5.13) - 0.5) * 0.25; }
// the feather of row q at column c: its place across (f, 0 to 1), its number, and where its tip edge lies (rows)
float plTip(float q, float c, float fluff, out float f, out float id) {
  float cc = c + plStagger(q);
  f = fract(cc);
  id = floor(cc) + q * 311.0;
  float x = 2.0 * f - 1.0;
  float edge = mix(sqrt(max(1.0 - x * x, 0.0)), 1.0 - abs(x), p_plPoint);
  edge += fluff * (kn(vec2(f * 14.0, id * 1.7)) - 0.5) * p_plFluffEdge;
  return q + 1.0 + p_plLap * clamp(edge, 0.0, 1.0);
}





