void look_1(inout Look k) {
  p_fwTint = texelFetch(lookSettings, ivec2(0, 1), 0).rgb;
  p_fwCut = texelFetch(lookSettings, ivec2(1, 1), 0).r;
  p_fwRough = texelFetch(lookSettings, ivec2(2, 1), 0).r;
  p_fwRelief = texelFetch(lookSettings, ivec2(3, 1), 0).r;
  p_fwSheen = texelFetch(lookSettings, ivec2(4, 1), 0).rgb;
  t_fwHawkWing = 0;
  t_fwHawkNormal = 1;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec4 fwD = picDataS3(t_fwHawkWing, s3);
    // the picture's colour is stored times its alpha (pictures.mjs): divided out, then made linear
    vec3 fwC = clamp(fwD.rgb / max(fwD.a, 0.02), 0.0, 1.0);
    fwC = mix(fwC / 12.92, pow((fwC + 0.055) / 1.055, vec3(2.4)), step(0.04045, fwC));
    k.colour = fwC * p_fwTint;
    k.alpha = fwD.a >= p_fwCut ? 1.0 : 0.0;
    // the normal map laid on the card as the colour is: its ways across and up the picture found from s3's change
    // across the pixel, as three's normal map finds a surface's ways from its uv
    vec3 fwM = picDataS3(t_fwHawkNormal, s3).xyz * 2.0 - 1.0;
    vec3 fwG = normalize(vNormal) * (gl_FrontFacing ? 1.0 : -1.0);
    vec3 fwQ0 = dFdx(-vViewPosition), fwQ1 = dFdy(-vViewPosition);
    vec2 fwSx = dFdx(s3), fwSy = dFdy(s3);
    vec3 fwP1 = cross(fwQ1, fwG), fwP0 = cross(fwG, fwQ0);
    vec3 fwT = fwP1 * fwSx.x + fwP0 * fwSy.x;
    vec3 fwB = -(fwP1 * fwSx.y + fwP0 * fwSy.y);
    float fwDet = max(dot(fwT, fwT), dot(fwB, fwB));
    float fwScale = fwDet == 0.0 ? 0.0 : (gl_FrontFacing ? 1.0 : -1.0) * inversesqrt(fwDet);
    k.normal = normalize(fwT * (fwM.x * p_fwRelief * fwScale) + fwB * (fwM.y * p_fwRelief * fwScale) + fwG * fwM.z);
    k.ownNormal = true;
    k.rough = p_fwRough;
    k.metal = 0.0;
    k.sheen = p_fwSheen;
    k.sheenRough = 0.5;

}

void look_2(inout Look k) {
  p_bkBase = texelFetch(lookSettings, ivec2(0, 2), 0).rgb;
  p_bkBody = texelFetch(lookSettings, ivec2(1, 2), 0).rgb;
  p_bkTip = texelFetch(lookSettings, ivec2(2, 2), 0).rgb;
  p_bkBaseTo = texelFetch(lookSettings, ivec2(3, 2), 0).r;
  p_bkTipFrom = texelFetch(lookSettings, ivec2(4, 2), 0).r;
  p_bkTipTo = texelFetch(lookSettings, ivec2(5, 2), 0).r;
  p_bkLines = texelFetch(lookSettings, ivec2(6, 2), 0).r;
  p_bkLineScale = texelFetch(lookSettings, ivec2(7, 2), 0).r;
  p_bkRidge = texelFetch(lookSettings, ivec2(8, 2), 0).r;
  p_bkPits = texelFetch(lookSettings, ivec2(9, 2), 0).r;
  p_bkScales = texelFetch(lookSettings, ivec2(10, 2), 0).r;
  p_bkScaleSize = texelFetch(lookSettings, ivec2(11, 2), 0).r;
  p_bkScaleRelief = texelFetch(lookSettings, ivec2(12, 2), 0).r;
  p_bkCrack = texelFetch(lookSettings, ivec2(13, 2), 0).rgb;
  p_bkMottle = texelFetch(lookSettings, ivec2(14, 2), 0).r;
  p_bkRough = texelFetch(lookSettings, ivec2(15, 2), 0).r;
  p_bkCoat = texelFetch(lookSettings, ivec2(16, 2), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float t = clamp(s3.x, 0.0, 1.0);
    vec3 c = mix(p_bkBase, p_bkBody, smoothstep(p_bkBaseTo * 0.6, p_bkBaseTo, t));
    c = mix(c, p_bkTip, smoothstep(p_bkTipFrom, max(p_bkTipTo, p_bkTipFrom + 0.001), t));
    // growth ridges along the beak, and pits between them
    float ridge = kn(vec2(uv.x * 8.0, uv.y * p_bkLineScale) + seed) * kfade(2.0 / p_bkLineScale);
    float pit = smoothstep(0.72, 0.9, kn(uv * p_bkLineScale * 1.7 + seed * 2.3)) * kfade(1.5 / p_bkLineScale);
    float mottle = kfbm4(uv * 60.0 + seed);
    c *= 1.0 + (ridge - 0.5) * p_bkLines;
    c *= 1.0 - 0.3 * pit * p_bkPits;
    c *= 1.0 + (mottle - 0.5) * p_bkMottle;
    // skin: small rounded scales, the cracks between them dark
    float cell, edge;
    kvor(uv / p_bkScaleSize + seed * 5.1, cell, edge);
    float fade = kfade(p_bkScaleSize);
    float bump = smoothstep(0.0, 0.3, edge) * fade;
    vec3 skinTone = mix(p_bkCrack, vec3(0.9 + 0.2 * cell), mix(1.0, bump, fade));
    c *= mix(vec3(1.0), skinTone, p_bkScales);
    k.colour = c;
    k.rough = mix(p_bkRough, min(1.0, p_bkRough + 0.25), p_bkScales * (1.0 - bump));
    k.metal = 0.0;
    k.height = (1.0 - p_bkScales) * (p_bkRidge * (ridge - 0.5) * 2.0 - 0.5 * p_bkRidge * pit * p_bkPits)
             + p_bkScales * p_bkScaleRelief * bump;
    k.ao = 1.0 - 0.3 * p_bkScales * (1.0 - bump) * fade;
    k.clearcoat = p_bkCoat * (1.0 - 0.7 * p_bkScales);
    k.clearcoatRough = 0.25;

}

