void look_4(inout Look k) {
  p_eyPupil = texelFetch(lookSettings, ivec2(0, 4), 0).rgb;
  p_eyIrisIn = texelFetch(lookSettings, ivec2(1, 4), 0).rgb;
  p_eyIrisOut = texelFetch(lookSettings, ivec2(2, 4), 0).rgb;
  p_eyRim = texelFetch(lookSettings, ivec2(3, 4), 0).rgb;
  p_eyRing = texelFetch(lookSettings, ivec2(4, 4), 0).rgb;
  p_eyPupilSize = texelFetch(lookSettings, ivec2(5, 4), 0).r;
  p_eyRimFrom = texelFetch(lookSettings, ivec2(6, 4), 0).r;
  p_eyFlecks = texelFetch(lookSettings, ivec2(7, 4), 0).r;
  p_eyFibres = texelFetch(lookSettings, ivec2(8, 4), 0).r;
  p_eyFibreRelief = texelFetch(lookSettings, ivec2(9, 4), 0).r;
  p_eyPupilSink = texelFetch(lookSettings, ivec2(10, 4), 0).r;
  p_eyBulge = texelFetch(lookSettings, ivec2(11, 4), 0).r;
  p_eyLid = texelFetch(lookSettings, ivec2(12, 4), 0).r;
  p_eyLidWide = texelFetch(lookSettings, ivec2(13, 4), 0).r;
  p_eyScales = texelFetch(lookSettings, ivec2(14, 4), 0).r;
  p_eyScaleRelief = texelFetch(lookSettings, ivec2(15, 4), 0).r;
  p_eyCrack = texelFetch(lookSettings, ivec2(16, 4), 0).rgb;
  p_eyRingRough = texelFetch(lookSettings, ivec2(17, 4), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float R = max(s2.x, 1e-5);
    float r = length(s3);
    float a = atan(s3.y, s3.x);
    float soft = 0.025;
    float eye = 1.0 - smoothstep(1.0 - soft, 1.0 + soft, r);
    // the iris: its colour, flecks and fibres running out from the pupil
    float fleck = kn(vec2(a * 14.0, r * 24.0) + seed) * kfade(R * 0.05);
    float fibre = kn(vec2(a * p_eyFibres / 6.2832, r * 3.0) + seed * 1.7) * kfade(R * 6.2832 / p_eyFibres);
    vec3 iris = mix(p_eyIrisIn, p_eyIrisOut, smoothstep(p_eyPupilSize, p_eyRimFrom, r));
    iris *= 1.0 + (fleck - 0.5) * p_eyFlecks + (fibre - 0.5) * 0.25;
    float inIris = smoothstep(p_eyPupilSize - soft, p_eyPupilSize + soft, r);
    vec3 c = mix(p_eyPupil, iris, inIris);
    c = mix(c, p_eyRim, smoothstep(p_eyRimFrom, 1.0, r));
    // the ring: rounded scales of skin, darker in the cracks between them
    float cell, edge;
    float d = kvor(s3 * p_eyScales + seed * 3.1, cell, edge);
    float scaleFade = kfade(R / p_eyScales);
    float bump = smoothstep(0.0, 0.35, edge) * scaleFade;
    vec3 ring = p_eyRing * (0.85 + 0.3 * cell);
    ring = mix(ring * p_eyCrack, ring, mix(1.0, bump, scaleFade));
    // the lids: a soft fold standing proud just outside the eye's edge, creased where it tucks under
    float lid = smoothstep(1.0, 1.0 + 0.4 * p_eyLidWide, r) * (1.0 - smoothstep(1.0 + 0.4 * p_eyLidWide, 1.0 + p_eyLidWide, r));
    float crease = 1.0 - smoothstep(1.0, 1.0 + 0.25 * p_eyLidWide, r);
    ring *= 1.0 - 0.45 * crease;
    k.colour = mix(ring, c, eye);
    k.rough = mix(p_eyRingRough, 0.25, eye);
    k.metal = 0.0;
    float dome = p_eyBulge * sqrt(max(0.0, 1.0 - r * r));
    float iris3 = inIris * (fibre - 0.5) * p_eyFibreRelief - (1.0 - inIris) * p_eyPupilSink;
    float skin3 = p_eyLid * lid + p_eyScaleRelief * bump * (1.0 - lid);
    k.height = R * mix(skin3, dome + iris3, eye);
    k.ao = mix(1.0 - 0.5 * crease * (1.0 - eye), 1.0, eye);
    k.clearcoat = eye;
    k.clearcoatRough = 0.02;

}

