    float bar = smoothstep(0.25, 0.35, band) * smoothstep(0.75, 0.65, band) * step(p_plFringe * 0.5, tipDist);
    bar *= mix(p_plBarUp, p_plBarUnder, under) * kfade(L * 2.5 / p_plBars);
    float fringe = smoothstep(p_plFringe, p_plFringe * 0.45, tipDist) * mix(p_plFringeUp, p_plFringeUnder, under);
    fringe *= kfade(L * p_plFringe);
    float spotD = length(vec2((tipDist - p_plSpot * 1.3) / p_plSpot, (f - 0.5) / (p_plSpot * 1.2)));
    float spot = smoothstep(1.0, 0.7, spotD) * p_plSpotOn * kfade(L * p_plSpot);
    c = mix(c, p_plMark, max(streak, bar) * feather);
    c = mix(c, p_plEdge, fringe * feather);
    c = mix(c, p_plSpotColour, spot * feather);
    c *= 0.9 + 0.2 * (barb - 0.5);
    c *= 1.0 - 0.15 * shaft;
    // the shadow on this feather just past the tip of the one over it
    float shade = 1.0 - p_plShade * exp(-past * p_plShadeFall) * feather;
    k.colour = c * shade;
    k.ao = mix(1.0, 0.6 + 0.4 * s, feather);
    k.rough = mix(p_plRough, 1.0, fluff * p_plFluffRough);
    k.metal = 0.0;
    // each feather rises from the tip over it to its own tip edge, where it steps down onto the next
    k.height = L * (p_plLift * smoothstep(0.0, 1.0, s) * feather + 0.02 * barb);
    k.sheen = p_plSheen * (1.0 + fluff);
    k.sheenRough = 0.5;
    float irid = clamp(mix(p_plIrid, max(p_plIrid, p_plIridNeck), max(neck, head * 0.5)), 0.0, 1.0);
    k.iridescence = irid * (1.0 - fluff * p_plFluffGloss);
    k.iridIor = p_plIridIor;
    k.iridThick = p_plIridThick;
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(fract(id * 0.37), fract(id * 0.61), fract(id * 0.83));

}

void look_1(inout Look k) {
  p_fwTint = texelFetch(lookSettings, ivec2(0, 1), 0).rgb;
  p_fwCut = texelFetch(lookSettings, ivec2(1, 1), 0).r;
  p_fwRough = texelFetch(lookSettings, ivec2(2, 1), 0).r;
  p_fwRelief = texelFetch(lookSettings, ivec2(3, 1), 0).r;
  p_fwSheen = texelFetch(lookSettings, ivec2(4, 1), 0).rgb;
  t_fwHawkWing = 0;
  t_fwHawkNormal = 1;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec4 fwD = picDataS3(t_fwHawkWing, s3);
    // the picture's colour is stored times its alpha (pictures.mjs): divided out, then made linear
    vec3 fwC = clamp(fwD.rgb / max(fwD.a, 0.02), 0.0, 1.0);
    fwC = mix(fwC / 12.92, pow((fwC + 0.055) / 1.055, vec3(2.4)), step(0.04045, fwC));
    k.colour = fwC * p_fwTint;
    k.alpha = fwD.a >= p_fwCut ? 1.0 : 0.0;
    // the normal map laid on the card as the colour is: its ways across and up the picture found from s3's change
    // across the pixel, as three's normal map finds a surface's ways from its uv
    vec3 fwM = picDataS3(t_fwHawkNormal, s3).xyz * 2.0 - 1.0;
    vec3 fwG = normalize(vNormal) * (gl_FrontFacing ? 1.0 : -1.0);
    vec3 fwQ0 = dFdx(-vViewPosition), fwQ1 = dFdy(-vViewPosition);
    vec2 fwSx = dFdx(s3), fwSy = dFdy(s3);
    vec3 fwP1 = cross(fwQ1, fwG), fwP0 = cross(fwG, fwQ0);
    vec3 fwT = fwP1 * fwSx.x + fwP0 * fwSy.x;
    vec3 fwB = -(fwP1 * fwSx.y + fwP0 * fwSy.y);
    float fwDet = max(dot(fwT, fwT), dot(fwB, fwB));
    float fwScale = fwDet == 0.0 ? 0.0 : (gl_FrontFacing ? 1.0 : -1.0) * inversesqrt(fwDet);
    k.normal = normalize(fwT * (fwM.x * p_fwRelief * fwScale) + fwB * (fwM.y * p_fwRelief * fwScale) + fwG * fwM.z);
    k.ownNormal = true;
    k.rough = p_fwRough;
    k.metal = 0.0;
    k.sheen = p_fwSheen;
    k.sheenRough = 0.5;

}

