    c = mix(c, p_bkTip, smoothstep(p_bkTipFrom, max(p_bkTipTo, p_bkTipFrom + 0.001), t));
    // growth ridges along the beak, and pits between them
    float ridge = kn(vec2(uv.x * 8.0, uv.y * p_bkLineScale) + seed) * kfade(2.0 / p_bkLineScale);
    float pit = smoothstep(0.72, 0.9, kn(uv * p_bkLineScale * 1.7 + seed * 2.3)) * kfade(1.5 / p_bkLineScale);
    float mottle = kfbm4(uv * 60.0 + seed);
    c *= 1.0 + (ridge - 0.5) * p_bkLines;
    c *= 1.0 - 0.3 * pit * p_bkPits;
    c *= 1.0 + (mottle - 0.5) * p_bkMottle;
    // skin: small rounded scales, the cracks between them dark
    float cell, edge;
    kvor(uv / p_bkScaleSize + seed * 5.1, cell, edge);
    float fade = kfade(p_bkScaleSize);
    float bump = smoothstep(0.0, 0.3, edge) * fade;
    vec3 skinTone = mix(p_bkCrack, vec3(0.9 + 0.2 * cell), mix(1.0, bump, fade));
    c *= mix(vec3(1.0), skinTone, p_bkScales);
    k.colour = c;
    k.rough = mix(p_bkRough, min(1.0, p_bkRough + 0.25), p_bkScales * (1.0 - bump));
    k.metal = 0.0;
    k.height = (1.0 - p_bkScales) * (p_bkRidge * (ridge - 0.5) * 2.0 - 0.5 * p_bkRidge * pit * p_bkPits)
             + p_bkScales * p_bkScaleRelief * bump;
    k.ao = 1.0 - 0.3 * p_bkScales * (1.0 - bump) * fade;
    k.clearcoat = p_bkCoat * (1.0 - 0.7 * p_bkScales);
    k.clearcoatRough = 0.25;

}

