void look_4(inout Look k) {
  p_eyPupil = texelFetch(lookSettings, ivec2(0, 4), 0).rgb;
  p_eyIrisIn = texelFetch(lookSettings, ivec2(1, 4), 0).rgb;
  p_eyIrisOut = texelFetch(lookSettings, ivec2(2, 4), 0).rgb;
