void look_6(inout Look k) {
  p_lgSkin = texelFetch(lookSettings, ivec2(0, 6), 0).rgb;
  p_lgPlate = texelFetch(lookSettings, ivec2(1, 6), 0).rgb;
  p_lgPad = texelFetch(lookSettings, ivec2(2, 6), 0).rgb;
  p_lgCrack = texelFetch(lookSettings, ivec2(3, 6), 0).rgb;
  p_lgPlateWide = texelFetch(lookSettings, ivec2(4, 6), 0).r;
  p_lgScale = texelFetch(lookSettings, ivec2(5, 6), 0).r;
  p_lgPadScale = texelFetch(lookSettings, ivec2(6, 6), 0).r;
  p_lgRelief = texelFetch(lookSettings, ivec2(7, 6), 0).r;
  p_lgPlateRelief = texelFetch(lookSettings, ivec2(8, 6), 0).r;
  p_lgMottle = texelFetch(lookSettings, ivec2(9, 6), 0).r;
  p_lgRough = texelFetch(lookSettings, ivec2(10, 6), 0).r;
  p_lgCoat = texelFetch(lookSettings, ivec2(11, 6), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float along = s3.x, round_ = s3.y, girth = max(s2.y, 1e-4), plateLen = max(s2.x, 1e-4);
    float across = round_ * girth;
    float topness = abs(round_);
    // the plates: on the top band, each row plateLen long, its lower edge lapping the next
    float band = 1.0 - smoothstep(p_lgPlateWide * 0.5 - 0.04, p_lgPlateWide * 0.5 + 0.02, topness);
    float row = along / plateLen;
    float f = fract(row);
    float plateFade = kfade(plateLen * 0.5);
    float seam = (1.0 - smoothstep(0.0, 0.12, f)) * plateFade;
    float dome = sin(3.14159 * f) * (1.0 - smoothstep(0.25, 0.5, abs(across) / max(girth * p_lgPlateWide, 1e-5)));
    float plateTone = kh1(floor(row) * 3.7 + seed);
    // the small scales round the sides and back, or the pads underneath
    float isPad = s2.z * smoothstep(0.3, 0.38, topness);
    float size = girth * mix(p_lgScale, p_lgPadScale, isPad);
    float cell, edge;
    kvor(vec2(along, across) / size + seed * 4.3, cell, edge);
    float scaleFade = kfade(size);
    float bump = smoothstep(0.0, 0.35, edge) * scaleFade;
    vec3 skin = mix(p_lgSkin, p_lgPad, isPad) * (0.9 + 0.2 * cell);
    skin = mix(skin * p_lgCrack, skin, mix(1.0, bump, scaleFade));
    vec3 plate = p_lgPlate * (0.88 + 0.24 * plateTone);
    plate = mix(plate, plate * p_lgCrack, seam);
    vec3 c = mix(skin, plate, band);
    c *= 1.0 + (kfbm4(vec2(along, across) * 40.0 + seed) - 0.5) * p_lgMottle;
    k.colour = c;
    k.rough = mix(p_lgRough, p_lgRough - 0.15, band);
    k.metal = 0.0;
    float scales = girth * p_lgRelief * mix(1.0, 2.0, isPad) * bump;
    float plates = girth * p_lgPlateRelief * (f * plateFade + 0.5 * dome);
    k.height = mix(scales, plates, band);
    k.ao = 1.0 - 0.35 * mix((1.0 - bump) * scaleFade, seam, band);
    k.clearcoat = p_lgCoat;
    k.clearcoatRough = 0.3;

}

